            if not row["date"].startswith(month):
                continue
            total += Decimal(line_amount(int(row["quantity"]), int(row["unit_price_cents"]),
                                         Decimal(row["tax_rate"])))
    return half_up(total)


if __name__ == "__main__":
    import sys
    print(monthly_total(sys.argv[1]))

